from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self._spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self._option = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self._fast = SimpleMovingAverage(5)
        self._slow = SimpleMovingAverage(20)

        self._five_minute = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self._spy, self._five_minute)

        self._entry_signal_time = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._held_option = None
        self._entry_fill_price = None
        self._block_entries_on = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_safety()
        self._evaluate_exits(data)

        if self._entry_signal_time != self.Time:
            return

        self._entry_signal_time = None

        if self._block_entries_on == self.Time.date():
            return

        if self._held_option is not None and self.Portfolio[self._held_option].Quantity != 0:
            return

        if self._is_order_open(self._entry_order_id):
            return

        spy_bar = data.Bars.get(self._spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Entry skipped: no current SPY trade bar.")
            return

        chain = data.OptionChains.get(self._option)
        if chain is None:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        today = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - today).days >= 7
        ]

        if not eligible:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        expiry = min(contract.Expiry.date() for contract in eligible)
        minimum_strike = spy_bar.Close * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike.")
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self._entry_order_id = ticket.OrderId
            self.Debug(
                f"Entry submitted: {selected.Symbol} "
                f"expiry {selected.Expiry.date()} strike {selected.Strike}"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self._held_option = order_event.Symbol
                self._entry_fill_price = order_event.FillPrice
                self._entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} @ {order_event.FillPrice:.2f}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._entry_order_id = None
                self.Debug(f"Entry closed without fill: {order_event.Symbol}")

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} @ {order_event.FillPrice:.2f}"
                )
                self._exit_order_id = None
                self._held_option = None
                self._entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_order_id = None

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        had_ready_averages = self._fast.IsReady and self._slow.IsReady
        previous_fast = self._fast.Current.Value
        previous_slow = self._slow.Current.Value

        self._fast.Update(bar.EndTime, bar.Close)
        self._slow.Update(bar.EndTime, bar.Close)

        if not had_ready_averages or not self._fast.IsReady or not self._slow.IsReady:
            return

        is_bullish_cross = (
            previous_fast <= previous_slow
            and self._fast.Current.Value > self._slow.Current.Value
        )

        end_time = bar.EndTime.time()
        is_eligible_time = (
            end_time >= datetime.strptime("09:45", "%H:%M").time()
            and end_time <= datetime.strptime("14:30", "%H:%M").time()
        )

        if is_bullish_cross and is_eligible_time:
            self._entry_signal_time = bar.EndTime

    def _evaluate_exits(self, data: Slice):
        if self._held_option is None:
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity <= 0:
            return

        if self._is_trading_day_before_expiry() and self.Time.hour == 15 and self.Time.minute == 45:
            self._submit_option_exit("pre-expiration time stop")
            return

        if self._entry_fill_price is None or self._entry_fill_price <= 0:
            return

        chain = data.OptionChains.get(self._option)
        if chain is None:
            return

        held_contract = next(
            (contract for contract in chain if contract.Symbol == self._held_option),
            None
        )
        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_fill_price * 1.50:
            self._submit_option_exit("50% profit target")

    def _handle_expiration_safety(self):
        if self._held_option is None:
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity <= 0:
            return

        expiry = self._held_option.ID.Date.date()
        if self.Time.date() >= expiry:
            self._block_entries_on = self.Time.date()
            self.Debug(f"Expiration safety exit: {self._held_option}")
            self._submit_option_exit("expiration safety")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self._spy].Quantity
        if quantity == 0:
            return

        open_orders = self.Transactions.GetOpenOrders(self._spy)
        if any(order.Quantity * quantity < 0 for order in open_orders):
            return

        self._block_entries_on = self.Time.date()
        self.Debug(f"Unexpected SPY exercise/assignment position: {quantity}. Liquidating.")
        self.MarketOrder(self._spy, -quantity)

    def _is_trading_day_before_expiry(self):
        if self._held_option is None:
            return False

        expiry = self._held_option.ID.Date.date()
        hours = self.Securities[self._spy].Exchange.Hours
        candidate = self.Time.date() + timedelta(days=1)

        while not hours.IsDateOpen(datetime.combine(candidate, datetime.min.time()), False):
            candidate += timedelta(days=1)

        return candidate == expiry

    def _submit_option_exit(self, reason: str):
        if self._held_option is None or self._is_order_open(self._exit_order_id):
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity <= 0:
            return

        for order in self.Transactions.GetOpenOrders(self._held_option):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, "Replacing existing exit order")

        ticket = self.MarketOrder(self._held_option, -quantity)
        if ticket is not None:
            self._exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted ({reason}): {self._held_option}")

    def _is_order_open(self, order_id):
        if order_id is None:
            return False

        order = self.Transactions.GetOrderById(order_id)
        if order is None:
            return False

        return order.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

