from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA, False).Symbol
        self.Securities[self.option].SetFilter(
            -100, 100, timedelta(days=0), timedelta(days=730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.entry_signal_pending = False

        self.held_symbol = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.assignment_order_id = None
        self.expiration_block_date = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        had_ready_averages = self.fast.IsReady and self.slow.IsReady
        prior_fast = float(self.fast.Current.Value) if had_ready_averages else None
        prior_slow = float(self.slow.Current.Value) if had_ready_averages else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        is_bullish_cross = (
            had_ready_averages
            and self.fast.IsReady
            and self.slow.IsReady
            and prior_fast <= prior_slow
            and float(self.fast.Current.Value) > float(self.slow.Current.Value)
        )

        bar_end_time = bar.EndTime.time()
        if is_bullish_cross and time(9, 45) <= bar_end_time <= time(14, 30):
            self.entry_signal_pending = True

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = float(self.fast.Current.Value)
            self.previous_slow = float(self.slow.Current.Value)

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationProcessing()

        if self.HasHeldOption():
            self.EvaluateOptionExit(data)

        if self.entry_signal_pending:
            self.entry_signal_pending = False
            self.TryEnterCall(data)

    def TryEnterCall(self, data):
        if self.expiration_block_date == self.Time.date():
            return

        if self.HasHeldOption() or self.EntryOrderIsOpen():
            return

        if not data.OptionChains.ContainsKey(self.option):
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        chain = data.OptionChains[self.option]
        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        spot = float(self.Securities[self.spy].Price)
        minimum_strike = 1.01 * spot

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike at selected expiration.")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        contract = candidates[0]

        ticket = self.MarketOrder(contract.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_symbol = contract.Symbol
        self.held_expiry = contract.Expiry
        self.entry_fill_price = None
        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry {contract.Expiry.date()}, "
            f"strike {contract.Strike}."
        )

    def EvaluateOptionExit(self, data):
        if self.EntryOrderIsOpen() or self.ExitOrderIsOpen():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.IsPreExpirationTimeStop():
            self.SubmitExit("pre-expiration time stop")
            return

        if not data.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = data.QuoteBars[self.held_symbol]
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0 or self.entry_fill_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit("50% profit target")

    def HandleExpirationProcessing(self):
        if not self.HasHeldOption():
            return

        if self.Time.date() >= self.held_expiry.date():
            self.expiration_block_date = self.Time.date()
            if not self.ExitOrderIsOpen():
                self.SubmitExit("expiration processing")
            self.Debug(f"Expiration processing: liquidating {self.held_symbol}.")

    def HandleUnexpectedSpyHolding(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self.assignment_order_id is None or not self.IsOrderOpen(self.assignment_order_id):
            ticket = self.MarketOrder(self.spy, -quantity)
            self.assignment_order_id = ticket.OrderId
            self.Debug(
                f"Unexpected SPY exercise/assignment holding ({quantity}); "
                "submitted market liquidation."
            )

    def IsPreExpirationTimeStop(self):
        if self.Time.hour != 15 or self.Time.minute != 45:
            return False

        expiry_date = self.held_expiry.date()
        current_date = self.Time.date()
        if current_date >= expiry_date:
            return False

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        next_trading_date = current_date + timedelta(days=1)

        while next_trading_date <= expiry_date:
            session_start = datetime.combine(next_trading_date, time.min)
            if exchange_hours.IsDateOpen(session_start):
                return next_trading_date == expiry_date
            next_trading_date += timedelta(days=1)

        return False

    def SubmitExit(self, reason):
        if not self.HasHeldOption() or self.ExitOrderIsOpen():
            return

        self.CancelOpenExitOrders()
        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted for {self.held_symbol}: {reason}.")

    def CancelOpenExitOrders(self):
        if self.held_symbol is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id, "Replacing open exit order.")

    def HasHeldOption(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity > 0
        )

    def EntryOrderIsOpen(self):
        return self.entry_order_id is not None and self.IsOrderOpen(self.entry_order_id)

    def ExitOrderIsOpen(self):
        return self.exit_order_id is not None and self.IsOrderOpen(self.exit_order_id)

    def IsOrderOpen(self, order_id):
        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.FillQuantity > 0 and self.entry_fill_price is None:
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_symbol} at {self.entry_fill_price:.2f}."
                )

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                if order_event.Status != OrderStatus.Filled:
                    self.Debug(f"Entry order ended with status {order_event.Status}.")
                    if not self.HasHeldOption():
                        self.held_symbol = None
                        self.held_expiry = None
                        self.entry_fill_price = None
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.held_symbol = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Exit order ended with status {order_event.Status}.")
                self.exit_order_id = None

        if order_event.OrderId == self.assignment_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.assignment_order_id = None

