        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-200, 200, timedelta(days=0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self._closes = deque(maxlen=20)

        self._bucket_date = None
        self._bucket_end_minute = None
        self._bucket_close = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_price = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.equity_exit_ticket = None
        self.blocked_entry_date = None

    def OnData(self, data):
        self._handle_unexpected_spy_position()
        self._handle_expiration(data)
        self._handle_option_exits(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar, data)

    def _update_five_minute_bar(self, minute_bar, data):
        end_time = minute_bar.EndTime
        minute_of_day = end_time.hour * 60 + end_time.minute
        bucket_end = ((minute_of_day + 4) // 5) * 5

        if bucket_end >= 24 * 60:
            return

        current_date = end_time.date()
        bucket_key_changed = (
            self._bucket_date != current_date or
            self._bucket_end_minute != bucket_end
        )

        if bucket_key_changed:
            # A prior interval without its closing minute is intentionally discarded.
            self._bucket_date = current_date
            self._bucket_end_minute = bucket_end
            self._bucket_close = minute_bar.Close
        else:
            self._bucket_close = minute_bar.Close

        if minute_of_day != bucket_end:
            return

        close = self._bucket_close
        self._bucket_date = None
        self._bucket_end_minute = None
        self._bucket_close = None

        self._on_five_minute_close(end_time, close, data)

    def _on_five_minute_close(self, end_time, close, data):
        prior = list(self._closes)

        if len(prior) == 20:
            previous_fast = sum(prior[-5:]) / 5.0
            previous_slow = sum(prior) / 20.0

            self._closes.append(close)
            current = list(self._closes)
            current_fast = sum(current[-5:]) / 5.0
            current_slow = sum(current) / 20.0

            bullish_cross = (
                previous_fast <= previous_slow and
                current_fast > current_slow
            )

            if bullish_cross:
                time_of_day = end_time.time()
                if (
                    time_of_day >= datetime.min.time().replace(hour=9, minute=45) and
                    time_of_day <= datetime.min.time().replace(hour=14, minute=30)
                ):
                    self._try_enter_call(data)
        else:
            self._closes.append(close)

    def _try_enter_call(self, data):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Entry skipped: SPY price unavailable")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Entry skipped: no eligible expiration")
            return

        expiry = expiries[0]
        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= spot * 1.01
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible call strike")
            return

        contract = sorted(
            candidates,
            key=lambda x: (float(x.Strike), str(x.Symbol))
        )[0]

        self.held_symbol = contract.Symbol
        self.held_expiry = contract.Expiry
        self.entry_price = None
        self.exit_ticket = None
        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)

        self.Debug(
            f"Entry submitted: {contract.Symbol} expiry {expiry} strike {contract.Strike}"
        )

    def _handle_option_exits(self, data):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self.entry_price is not None:
            quote = data.QuoteBars.get(self.held_symbol)
            if quote is not None and quote.Bid is not None and quote.Ask is not None:
                bid = quote.Bid.Close
                ask = quote.Ask.Close
                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= self.entry_price * 1.50:
                        self._submit_option_exit("profit target")
                        return

        if self.held_expiry is not None:
            previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
                self.held_expiry
            ).date()

            if (
                self.Time.date() == previous_trading_day and
                self.Time.hour == 15 and
                self.Time.minute == 45
            ):
                self._submit_option_exit("pre-expiration time stop")

    def _handle_expiration(self, data):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() < self.held_expiry.date():
            return

        self.blocked_entry_date = self.Time.date()

        if self.Portfolio[self.held_symbol].Invested and not self._ticket_is_open(self.exit_ticket):
            self._submit_option_exit("expiration safeguard")

    def _submit_option_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self._ticket_is_open(self.equity_exit_ticket):
            return

        self.blocked_entry_date = self.Time.date()
        self.equity_exit_ticket = self.MarketOrder(self.spy, -quantity)
        self.Debug(f"Unexpected SPY exercise/assignment position liquidated: {quantity}")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {self.entry_price}"
                )
                self.entry_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry canceled/invalid: {order_event.Symbol}")
                self.entry_ticket = None
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}")
                self.exit_ticket = None
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

        if (
            self.equity_exit_ticket is not None and
            order_event.OrderId == self.equity_exit_ticket.OrderId and
            order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]
        ):
            self.equity_exit_ticket = None

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

