        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self._ticket_is_open(self.equity_exit_ticket):
            return

        self.blocked_entry_date = self.Time.date()
        self.equity_exit_ticket = self.MarketOrder(self.spy, -quantity)
        self.Debug(f"Unexpected SPY exercise/assignment position liquidated: {quantity}")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
