from datetime import timedelta, time

from QuantConnect import (
    DataNormalizationMode,
    Market,
    OptionRight,
    OrderStatus,
    Resolution,
    TimeZones,
)
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Consolidators import TradeBarConsolidator


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(timedelta(0), timedelta(730))
        )
        self.option_symbol = self.option.Symbol

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_bar_end = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_exit_order_id = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.append(float(bar.Close))
        if len(self.closes) > 20:
            self.closes.pop(0)

        if len(self.closes) < 20:
            return

        fast = sum(self.closes[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end_time = bar.EndTime.time()
        if crossover and time(9, 45) <= bar_end_time <= time(14, 30):
            self.pending_entry_bar_end = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()

        if self.held_symbol is not None and self.held_expiry is not None:
            if self.Time.date() >= self.held_expiry.date():
                self.no_entry_date = self.Time.date()
                if self.Portfolio[self.held_symbol].Invested:
                    self.Debug(
                        f"Expiration processing: liquidating {self.held_symbol}."
                    )
                    self.SubmitExit("expiration processing", True)

        self.EvaluateExit(data)

        if (
            self.pending_entry_bar_end is not None
            and self.Time >= self.pending_entry_bar_end
        ):
            pending_bar_end = self.pending_entry_bar_end
            self.pending_entry_bar_end = None

            if self.Time != pending_bar_end:
                return

            self.TryEnter(data)

    def TryEnter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.entry_order_id is not None:
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Entry skipped: no SPY option chain in the current Slice.")
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("Entry skipped: SPY has no valid current price.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry_date = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= minimum_expiry_date
            }
        )
        if not eligible_expiries:
            self.Debug("Entry skipped: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at the selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol)),
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_expiry = selected.Expiry
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def EvaluateExit(self, data):
        if (
            self.held_symbol is None
            or self.entry_fill_price is None
            or not self.Portfolio[self.held_symbol].Invested
        ):
            return

        if self.IsFinalTradingDayTimeStop():
            self.Debug(f"Time-stop exit submitted for {self.held_symbol}.")
            self.SubmitExit("15:45 pre-expiration time stop", False)
            return

        if self.exit_order_id is not None:
            return

        contract = self.GetHeldContractFromSlice(data)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.Debug(
                f"Profit-target exit submitted for {self.held_symbol} at midpoint "
                f"{midpoint:.2f}."
            )
            self.SubmitExit("50 percent profit target", False)

    def GetHeldContractFromSlice(self, data):
        if self.option_symbol not in data.OptionChains:
            return None

        for contract in data.OptionChains[self.option_symbol]:
            if contract.Symbol == self.held_symbol:
                return contract
        return None

    def IsFinalTradingDayTimeStop(self):
        if self.held_expiry is None or self.Time.time() < time(15, 45):
            return False

        previous_trading_day = self.held_expiry.date() - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        return self.Time.date() == previous_trading_day

    def SubmitExit(self, reason, replace_existing):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        if self.exit_order_id is not None:
            if not replace_existing:
                return
            self.Transactions.CancelOrder(self.exit_order_id, reason)

