        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

        self.schedule.on(
            self.date_rules.every_day(self.spy),
            self.time_rules.at(15, 45),
            self._expiration_eve_exit
        )

    def _on_five_minute_bar(self, sender, bar):
        self.fast.update(bar.end_time, bar.close)
        self.slow.update(bar.end_time, bar.close)

        if self.fast.is_ready and self.slow.is_ready:
            is_crossover = (
                self.previous_fast is not None
                and self.previous_fast <= self.previous_slow
                and self.fast.current.value > self.slow.current.value
            )

            end_time = bar.end_time.time()
            if is_crossover and end_time >= time(9, 45) and end_time <= time(14, 30):
                self.pending_entry_time = bar.end_time

            self.previous_fast = self.fast.current.value
            self.previous_slow = self.slow.current.value

    def on_data(self, data):
        self._handle_unexpected_spy_position()
        self._handle_expiration(data)

        if self.held_option is not None and self.portfolio[self.held_option].invested:
            self._check_profit_target(data)

        if self.pending_entry_time is not None:
            pending_time = self.pending_entry_time
            self.pending_entry_time = None

            if pending_time == self.time:
                self._try_enter(data)

    def _try_enter(self, data):
        if self.entry_blocked_date == self.time.date():
            return

        if self.held_option is not None and self.portfolio[self.held_option].invested:
            return

        if self.entry_order_id is not None and self._order_is_open(self.entry_order_id):
            return

        chains = list(data.option_chains.values())
        if not chains:
            self.debug(f"{self.time}: Entry skipped: no option chain.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(chain)

        current_spy_price = self.securities[self.spy].price
        if current_spy_price <= 0:
            self.debug(f"{self.time}: Entry skipped: invalid SPY price.")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        eligible_expiries = sorted({
            contract.expiry.date()
            for contract in contracts
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.debug(f"{self.time}: Entry skipped: no eligible expiration.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = current_spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug(f"{self.time}: Entry skipped: no eligible call strike.")
            return

        selected = min(candidates, key=lambda c: (c.strike, str(c.symbol)))
        ticket = self.market_order(selected.symbol, 1)

        self.entry_order_id = ticket.order_id
        self.held_option = selected.symbol
        self.held_expiry = selected.expiry.date()
        self.entry_fill_price = None

        self.debug(
            f"{self.time}: Entering {selected.symbol} "
            f"expiry {selected.expiry.date()} strike {selected.strike}."
        )

    def _check_profit_target(self, data):
        if self.entry_fill_price is None or self._has_open_exit_order():
            return

        if self.held_option not in data.quote_bars:
            return

        quote = data.quote_bars[self.held_option]
        bid = quote.bid.close if quote.bid is not None else 0
        ask = quote.ask.close if quote.ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("profit target")

    def _expiration_eve_exit(self):
        if self.held_option is None or not self.portfolio[self.held_option].invested:
            return

        if self.held_expiry is None or self._has_open_exit_order():
            return

        next_open = self.securities[self.spy].exchange.hours.get_next_market_open(
            self.time, False
        )

        if next_open.date() == self.held_expiry:
            self._submit_exit("expiration-eve time stop")

    def _handle_expiration(self, data):
        if self.held_option is None or not self.portfolio[self.held_option].invested:
            return

        if self.held_expiry is not None and self.time.date() >= self.held_expiry:
            self.entry_blocked_date = self.time.date()
            if not self._has_open_exit_order():
                self.debug(f"{self.time}: Expiration processing exit for {self.held_option}.")
                self._submit_exit("expiration processing")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.portfolio[self.held_option].quantity
        if quantity == 0:
            return

        for order in self.transactions.get_open_orders(self.held_option):
            self.transactions.cancel_order(order.id)

        ticket = self.market_order(self.held_option, -quantity)
        self.exit_order_id = ticket.order_id
        self.debug(f"{self.time}: Exiting {self.held_option}: {reason}.")

    def _handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy].quantity
        if quantity != 0 and not self._has_open_order_for_symbol(self.spy):
            self.debug(f"{self.time}: Unexpected SPY exercise/assignment position; liquidating.")
            self.market_order(self.spy, -quantity)

    def on_order_event(self, order_event):
        if order_event.order_id == self.entry_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.entry_fill_price = order_event.fill_price
                self.debug(
                    f"{self.time}: Entry filled {order_event.symbol} "
                    f"at {order_event.fill_price}."
                )
                self.entry_order_id = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.entry_order_id = None
                self.held_option = None
                self.held_expiry = None
                self.entry_fill_price = None

        if order_event.order_id == self.exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"{self.time}: Exit filled {order_event.symbol} "
                    f"at {order_event.fill_price}."
                )
                self.exit_order_id = None
                self.held_option = None
                self.held_expiry = None
                self.entry_fill_price = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.exit_order_id = None

    def _order_is_open(self, order_id):
        order = self.transactions.get_order_by_id(order_id)
        return order is not None and order.status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        )

    def _has_open_exit_order(self):
        return self.exit_order_id is not None and self._order_is_open(self.exit_order_id)

    def _has_open_order_for_symbol(self, symbol):
        return len(self.transactions.get_open_orders(symbol)) > 0

