from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute, Market.USA, False)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(0), timedelta(days=90))
        self.option_canonical = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)

        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.entry_contract = None
        self.exit_order_id = None
        self.spy_liquidation_order_id = None
        self.no_entry_date = None

        self.five_minute_consolidator = TradeBarConsolidator(
            self._five_minute_calendar
        )
        self.five_minute_consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(
            self.spy, self.five_minute_consolidator
        )

    def _five_minute_calendar(self, time):
        session_start = time.replace(hour=9, minute=30, second=0, microsecond=0)
        interval = int((time - session_start).total_seconds() // 300)
        start = session_start + timedelta(minutes=5 * interval)
        return CalendarInfo(start, start + timedelta(minutes=5))

    def _on_five_minute_bar(self, sender, bar):
        had_previous_slow = len(self.slow_closes) == 20

        if had_previous_slow:
            previous_fast = sum(self.fast_closes) / len(self.fast_closes)
            previous_slow = sum(self.slow_closes) / len(self.slow_closes)

        self.fast_closes.append(bar.Close)
        self.slow_closes.append(bar.Close)

        if not had_previous_slow:
            return

        current_fast = sum(self.fast_closes) / len(self.fast_closes)
        current_slow = sum(self.slow_closes) / len(self.slow_closes)

        is_bullish_cross = (
            previous_fast <= previous_slow and current_fast > current_slow
        )
        if not is_bullish_cross:
            return

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and
            (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )
        if not eligible_time:
            return

        current_slice = self.CurrentSlice
        if current_slice is not None:
            self._try_enter(current_slice)

    def OnData(self, data):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            if self.spy_liquidation_order_id is None:
                ticket = self.MarketOrder(self.spy, -spy_quantity)
                self.spy_liquidation_order_id = ticket.OrderId
                self.Debug("Unexpected SPY exercise/assignment position; liquidating")
            return

        if self.held_contract is not None:
            if self.Time.date() >= self.held_expiry.date():
                self.no_entry_date = self.Time.date()
                self._submit_exit("Expiration processing")
                return

            self._check_profit_target(data)

            if self._is_pre_expiration_time_stop():
                self._submit_exit("Pre-expiration time stop")

    def _try_enter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        if self.option_canonical not in data.OptionChains:
            self.Debug("Entry skipped: no current SPY option chain")
            return

        chain = data.OptionChains[self.option_canonical]
        minimum_expiry_date = self.Time.date() + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry_date
        })

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = self.Securities[self.spy].Price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))

        self.entry_contract = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
