from AlgorithmImports import *


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_five_minute_end = None
        self.current_five_minute_minutes = []

        self.held_contract = None
        self.entry_price = None
        self.last_time_stop_date = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_liquidation_order_id = None
        self.block_entries_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_option_exit(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar, data)

    def _update_five_minute_bar(self, minute_bar: TradeBar, data: Slice):
        end_time = minute_bar.EndTime
        minutes_after_midnight = end_time.hour * 60 + end_time.minute
        five_minute_end_minutes = ((minutes_after_midnight + 4) // 5) * 5
        five_minute_end = end_time.replace(
            hour=0, minute=0, second=0, microsecond=0
        ) + timedelta(minutes=five_minute_end_minutes)

        if self.current_five_minute_end is not None and five_minute_end != self.current_five_minute_end:
            # The previous interval did not receive all required minute bars.
            self.current_five_minute_minutes = []

        if five_minute_end != self.current_five_minute_end:
            self.current_five_minute_end = five_minute_end

        self.current_five_minute_minutes.append(minute_bar)

        if end_time != five_minute_end:
            return

        minute_bars = self.current_five_minute_minutes
        self.current_five_minute_minutes = []

        expected_ends = [
            five_minute_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if len(minute_bars) != 5 or [bar.EndTime for bar in minute_bars] != expected_ends:
            return

        self._on_completed_five_minute_bar(minute_bars[-1].Close, five_minute_end, data)

    def _on_completed_five_minute_bar(self, close: float, bar_end: datetime, data: Slice):
        self.closes.Add(float(close))

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_crossover:
            return

        bar_time = bar_end.time()
        if bar_time < time(9, 45) or bar_time > time(14, 30):
            return

        if self.block_entries_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        self._submit_entry(data, close)

    def _submit_entry(self, data: Slice, spy_price: float):
        if self.option_symbol not in data.OptionChains:
            self.Debug("Skipped entry: no SPY option chain in the current Slice.")
            return

        chain = data.OptionChains[self.option_symbol]
        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        contracts = list(chain)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Skipped entry: no expiration is at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at the selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {selected.Expiry.date()} "
            f"strike {selected.Strike}."
        )

    def _handle_option_exit(self, data: Slice):
        if self.held_contract is None:
            return

        if not self.Portfolio[self.held_contract].Invested:
            if self.exit_order_id is None:
                self._clear_option_state()
            return

        expiry_date = self.held_contract.ID.Date.date()

        # Do not intentionally carry an option into its expiration date.
        if self.Time.date() >= expiry_date:
            self.block_entries_date = self.Time.date()
            self._submit_exit("expiration safety liquidation")
            return

        if (
            self.last_time_stop_date == self.Time.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("15:45 pre-expiration time stop")
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None or self.entry_price is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted for {self.held_contract}: {reason}.")

    def _handle_unexpected_spy_position(self):
        if not self.Portfolio[self.spy].Invested or self.spy_liquidation_order_id is not None:
            return

        quantity = self.Portfolio[self.spy].Quantity
        ticket = self.MarketOrder(self.spy, -quantity)
        self.spy_liquidation_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position detected; liquidating.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.FillQuantity != 0 and order_event.FillPrice > 0:
                self.held_contract = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.last_time_stop_date = self._previous_spy_trading_day(
                    order_event.Symbol.ID.Date.date()
                )
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {self.entry_price:.2f}."
                )

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self._clear_option_state()
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_liquidation_order_id = None

    def _previous_spy_trading_day(self, expiry_date: date) -> date:
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _clear_option_state(self):
        self.held_contract = None
        self.entry_price = None
        self.last_time_stop_date = None
        self.exit_order_id = None

