from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.blocked_entry_date = None

        self.five_minute_consolidator = TradeBarConsolidator(
            self._five_minute_calendar
        )
        self.five_minute_consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(
            self.spy,
            self.five_minute_consolidator
        )

    def OnData(self, data):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()

        if self.pending_entry:
            self.pending_entry = False
            self._try_enter(data)

        self._evaluate_exits(data)

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Direction == OrderDirection.Buy:
                    self.held_option = order_event.Symbol
                    self.entry_fill_price = order_event.FillPrice
                    self.Debug(
                        f"Entry filled: {order_event.Symbol} at {order_event.FillPrice:.2f}"
                    )

            if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}"
                )
                if self.held_option == order_event.Symbol:
                    self.held_option = None
                    self.held_expiry = None
                    self.entry_fill_price = None
                    self.exit_ticket = None

        self._handle_unexpected_spy_position()

    def _five_minute_calendar(self, time):
        start = time.replace(
            minute=(time.minute // 5) * 5,
            second=0,
            microsecond=0
        )
        return CalendarInfo(start, timedelta(minutes=5))

    def _on_five_minute_bar(self, sender, bar):
        self.closes.append(bar.Close)

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime.time()
        if bullish_crossover and (
            bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)
        ):
            self.pending_entry = True

    def _try_enter(self, data):
        if self.blocked_entry_date == self.Time.date():
            return

        if self._has_option_holding() or self._order_is_open(self.entry_ticket):
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: SPY has no valid current price.")
            return

        current_date = self.Time.date()
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - current_date).days >= 7
        })

        if not eligible_expiries:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Entry skipped: no qualifying calls for expiration {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_expiry = selected.Expiry
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike:.2f}."
        )

    def _evaluate_exits(self, data):
        if not self._has_option_holding() or self.held_option is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        if self._is_pre_expiration_time_stop():
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        quote = data.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit(
                f"profit target reached at midpoint {midpoint:.2f}"
            )

    def _handle_expiration_processing(self):
        if not self._has_option_holding() or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.blocked_entry_date = self.Time.date()
            self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                f"Unexpected SPY exercise/assignment position detected: {quantity}. "
                "Submitting market liquidation."
            )
            self.MarketOrder(self.spy, -quantity)

    def _is_pre_expiration_time_stop(self):
        if self.held_expiry is None:
            return False

        expiry_midnight = datetime.combine(
            self.held_expiry.date(),
            datetime.min.time()
        )
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        prior_open = exchange_hours.GetPreviousMarketOpen(expiry_midnight, False)

        return (
            self.Time.date() == prior_open.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        )

    def _submit_exit(self, reason):
        if not self._has_option_holding() or self.held_option is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug(f"Exit submitted for {self.held_option}: {reason}.")

    def _has_option_holding(self):
        return (
            self.held_option is not None
            and self.Portfolio[self.held_option].Quantity != 0
        )

    def _order_is_open(self, ticket):
        return ticket is not None and ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        ]

